        {sipReady && fallbackReady && draft.checklist?.terminalConnected && !draft.checklist?.fallbackTest && ["active", "restored"].includes(draft.testRouting?.state) && <div className="mt-3"><p role="status">{draft.testRouting.state === "active" ? `Appelez ${draft.twilioNumber} et vérifiez la sonnerie et l’audio dans les deux sens. Le routage précédent sera rétabli avant la suite.` : "Le routage précédent est rétabli. Confirmez uniquement si l’appel réel a réussi."}</p><button type="button" className={`${button} mt-2`} disabled={busy} onClick={() => requestConfirmation("Confirmez-vous que l’appel réel a sonné et que l’audio fonctionnait dans les deux sens ?", () => action(async () => { const url = draft.fallbackFunction.url; if (draft.testRouting.state === "active") await axios.post(`${base}/fallback-test-routing`, { confirm: true, restore: true }, getAdminAuthConfig()); if (Date.now() - new Date(draft.fallbackProbeAt).getTime() > 15 * 60 * 1000) await axios.post(`${base}/fallback-probe`, { fallbackUrl: url }, getAdminAuthConfig()); await axios.post(`${base}/fallback-verification`, { fallbackUrl: url, confirm: true }, getAdminAuthConfig()); const result = await axios.post(`${base}/technical-finalize`, { confirm: true }, getAdminAuthConfig()); setTechnical(result.data); }))}>Confirmer l’appel réussi</button></div>}
