        {data.draft.sipCredentialOperation === "completed" && <div className="mt-2 flex flex-wrap gap-2">{!sipSecret && <button type="button" className={button} disabled={busy} onClick={() => requestConfirmation("Afficher le mot de passe SIP de cet établissement ?", () => action(async () => { const epoch = sipRequestEpoch.current; const result = await axios.post(`${base}/sip-secret`, { confirm: true }, getAdminAuthConfig({ headers: { "Cache-Control": "no-store" } })); if (sipRequestEpoch.current === epoch) { setSipSecret(result.data); setSipCopyStatus(""); } }))}>Afficher</button>}<button type="button" className={button} disabled={busy} onClick={() => requestConfirmation("Changer le mot de passe SIP ? Le terminal devra être reconfiguré.", () => action(async () => { sipRequestEpoch.current++; setSipSecret(null); setSipCopyStatus(""); await axios.post(`${base}/sip-rotate`, { confirm: true }, getAdminAuthConfig()); }))}>Changer le mot de passe</button></div>}
        {data.draft.sipCredentialOperation === "uncertain" && <p className="mt-2 text-red">Opération SIP incertaine : vérifiez les ressources avant reprise.</p>}
        {data.draft.sipCredentialOperation === "uncertain" && <button type="button" className={`${button} mt-2`} disabled={busy} onClick={() => { requestConfirmation("Rapprocher les ressources SIP et réappliquer le mot de passe préparé ? Si vous avez autorisé la reprise après vérification d’absence, les ressources manquantes seront créées.", () =>  action(() => axios.post(`${base}/sip-reconcile`, { confirm: true }, getAdminAuthConfig()))); }}>Rapprocher les identifiants</button>}
        {data.draft.sipCredentialOperation === "uncertain" && data.draft.sipCredentialSid && <button type="button" className={`${button} mt-2`} disabled={busy} onClick={() => { requestConfirmation("Reprendre la rotation SIP avec le mot de passe déjà préparé ?", () =>  action(() => axios.post(`${base}/sip-rotation-recover`, { confirm: true }, getAdminAuthConfig()))); }}>Reprendre la rotation</button>}
        {sipSecret && <div className="mt-3 rounded-xl bg-blue/10 p-3"><p>Domaine : {sipSecret.domain}</p><p>Identifiant : {sipSecret.username}</p><p>Mot de passe : <code>{sipSecret.password}</code></p><p className="mt-1 text-xs">Masqué automatiquement après une minute.</p><div className="mt-2 flex flex-wrap gap-2"><button type="button" className={button} onClick={() => { sipRequestEpoch.current++; setSipSecret(null); setSipCopyStatus(""); }}>Masquer</button><button type="button" className={button} onClick={async () => { try { if (!navigator.clipboard?.writeText) throw new Error("clipboard unavailable"); await navigator.clipboard.writeText(sipSecret.password); setSipCopyStatus("Mot de passe copié."); } catch (_) { setSipCopyStatus("Copie indisponible ; sélectionnez le mot de passe manuellement."); } }}>Copier</button></div>{sipCopyStatus && <p role="status" className="mt-1">{sipCopyStatus}</p>}</div>}
