      {data.draft?.sipCredentialOperation === "completed" && data.draft?.phoneNumberSid && (!data.liveExists || data.liveManaged) && <div className="rounded-xl border border-darkBlue/10 p-3 text-sm"><p className="font-semibold">Webhooks et secours</p><p>État : {data.draft.webhookOperation || "non commencé"}</p>{data.draft.fallbackFunction?.operation === "completed" ? <p className="mt-2" role="status">Function de secours publiée et réponse vérifiée. Configurez le terminal, puis testez un appel réel sur un numéro distinct avant de confirmer. Le secours reste à valider en conditions de panne.</p> : <details className="mt-2"><summary>Alternative : TwiML Bin manuel</summary><ol className="mt-2 list-decimal space-y-1 pl-5"><li>Dans la console Twilio du sous-compte, ouvrir Developer tools → TwiML Bins et créer un Bin.</li><li>Copier le TwiML ci-dessous dans le Bin, l’enregistrer puis copier son URL.</li><li>Vérifier sa réponse. Sur un numéro Twilio de test distinct, configurer temporairement ce Bin comme webhook Voice, appeler ce numéro et vérifier la sonnerie, le numéro appelant et l’audio.</li><li>Confirmer le test téléphonique réel, puis configurer le webhook du numéro attribué.</li></ol></details>}<button type="button" className={`${button} mt-2`} disabled={busy} onClick={() => action(async () => { const result = await axios.get(`${base}/fallback-template`, getAdminAuthConfig()); setFallbackTemplate(result.data); })}>Afficher le TwiML du restaurant</button>{fallbackTemplate && <pre className="mt-2 overflow-x-auto whitespace-pre-wrap rounded-xl bg-darkBlue/5 p-3 text-xs">{fallbackTemplate.twiml}</pre>}<label className="mt-2 block">URL du secours Twilio<input className={`${field} mt-1`} value={fallbackUrl} onChange={(event) => { setFallbackUrl(event.target.value); setFallbackProbeState(""); }} placeholder="https://handler.twilio.com/twiml/EH…" /></label><p className="mt-1 text-xs text-darkBlue/60">Le secours est hébergé par Twilio, indépendamment de Gusto. Tant que la route de test n’est pas activée, les appels en dépendent.</p><div className="mt-2 flex flex-wrap gap-2"><button type="button" className={button} disabled={busy || !fallbackUrl} onClick={() => action(async () => { setFallbackProbeState("checking"); try { await axios.post(`${base}/fallback-probe`, { fallbackUrl: fallbackUrl.trim() }, getAdminAuthConfig()); setFallbackProbeState(""); } catch (err) { setFallbackProbeState(err?.response?.data?.message || "Impossible de vérifier la réponse TwiML. Réessayez après contrôle de la connexion."); throw err; } })}>{fallbackProbeState === "checking" ? "Vérification en cours…" : "Vérifier la réponse TwiML"}</button>{fallbackProbeState && fallbackProbeState !== "checking" ? <p role="alert" className="text-red">{fallbackProbeState}</p> : !fallbackProbeState && data.draft.fallbackProbeAt && data.draft.fallbackProbeUrl === fallbackUrl.trim() && data.draft.fallbackProbeSipUri === `sip:${data.draft.sipUsername}@${data.draft.sipDomain}` && <p role="status" className="text-green-700">Réponse TwiML vérifiée · destination SIP conforme. Cette vérification ne remplace pas un essai téléphonique en panne.</p>}<button type="button" className={button} disabled={busy || !fallbackUrl || data.draft.fallbackProbeUrl !== fallbackUrl.trim() || !data.draft.fallbackProbeAt} onClick={() => { requestConfirmation(`Confirmer qu’un appel réel via ${fallbackUrl} a été testé pour ce restaurant ? Gusto finalisera ensuite les webhooks si les prérequis sont valides.`, () => action(async () => { await axios.post(`${base}/fallback-verification`, { fallbackUrl: fallbackUrl.trim(), confirm: true }, getAdminAuthConfig()); try { const result = await axios.post(`${base}/technical-finalize`, { confirm: true, functionConfirm: true }, getAdminAuthConfig()); setTechnical(result.data); } catch (_) { setTechnical({ status: "action_required", message: "Secours déclaré ; finalisation des webhooks à vérifier." }); } })); }}>Confirmer le test téléphonique</button><button type="button" className={button} disabled={busy || !fallbackUrl || data.draft.webhookOperation === "pending" || data.draft.verifiedFallbackUrl !== fallbackUrl.trim() || !data.draft.checklist?.fallbackTest} onClick={() => { requestConfirmation("Modifier le webhook du numéro Twilio ? Vérifiez le secours avant de confirmer.", () =>  action(() => axios.post(`${base}/webhooks`, { fallbackUrl: fallbackUrl.trim(), confirm: true }, getAdminAuthConfig()))); }}>Configurer et vérifier les webhooks</button></div></div>}
